import type { GlossaryEntry } from '../lib/reference-index-file';

export const glossaryIndex: GlossaryEntry[] = [
  { term: "Proposition", text: "A proposition (or statement) is a declarative sentence that is either true or false, but not both.", conceptId: "propositions", domain: "discrete", anchor: "section-definition-proposition" },
  { term: "Implication", text: "$p \\Rightarrow q$ (\"if $p$ then $q$\") is false only when $p$ is true and $q$ is false. Otherwise it is true. This is called the material conditional, and it is the connective that trips up most people.", conceptId: "logical-operators", domain: "discrete", anchor: "section-definition-implication" },
  { term: "Truth table", text: "Given a propositional formula with variables $p_1, \\ldots, p_n$, its truth table lists all $2^n$ assignments of truth values and the resulting value of the formula under each.", conceptId: "truth-tables", domain: "discrete", anchor: "section-definition-truth-table" },
  { term: "Logical equivalence", text: "Formulas $\\varphi$ and $\\psi$ are logically equivalent, written $\\varphi \\equiv \\psi$, if and only if $\\varphi \\Leftrightarrow \\psi$ is a tautology — i.e., the formulas agree on every row of their shared truth table.", conceptId: "logical-equivalence", domain: "discrete", anchor: "section-definition-logical-equivalence" },
  { term: "Definitions", text: "$\\varphi$ is a **tautology** (valid) if it is true under every assignment; a **contradiction** (unsatisfiable) if false under every assignment; **contingent** otherwise.", conceptId: "tautology-contradiction", domain: "discrete", anchor: "section-definition-definitions" },
  { term: "Predicate", text: "A predicate $P(x_1, \\ldots, x_n)$ is an expression containing variables $x_1, \\ldots, x_n$ that becomes a proposition when specific values are substituted for the variables.", conceptId: "predicates", domain: "discrete", anchor: "section-definition-predicate" },
  { term: "Quantifiers", text: "$\\forall x \\, P(x)$: \"$P(x)$ is true for every $x$ in the domain\". $\\exists x \\, P(x)$: \"$P(x)$ is true for at least one $x$ in the domain\".", conceptId: "quantifiers", domain: "discrete", anchor: "section-definition-quantifiers" },
  { term: "Set-builder notation", text: "$S = \\{ x \\in D : P(x) \\}$ denotes the set of all elements $x$ of the domain $D$ that satisfy the predicate $P(x)$.", conceptId: "set-basics", domain: "discrete", anchor: "section-definition-set-builder-notation" },
  { term: "Subset", text: "$A \\subseteq B$ means: for every $x$, if $x \\in A$ then $x \\in B$. Proper subset: $A \\subset B$ means $A \\subseteq B$ and $A \\ne B$.", conceptId: "subsets", domain: "discrete", anchor: "section-definition-subset" },
  { term: "Cartesian product", text: "$A \\times B = \\{ (a, b) : a \\in A \\text{ and } b \\in B \\}$. It has $|A| \\cdot |B|$ elements. Unlike union, the product is not commutative up to equality: in general $(1,2) \\ne (2,1)$.", conceptId: "cartesian-product", domain: "discrete", anchor: "section-definition-cartesian-product" },
  { term: "Power set", text: "$\\mathcal{P}(A) = \\{ S : S \\subseteq A \\}$. If $|A| = n$ then $|\\mathcal{P}(A)| = 2^n$.", conceptId: "power-set", domain: "discrete", anchor: "section-definition-power-set" },
  { term: "Function", text: "A function $f: A \\to B$ assigns exactly one output $f(a) \\in B$ to every input $a \\in A$. The domain $A$ is where inputs come from; the codomain $B$ is the declared space of allowed outputs. A function is therefore a typed, single-valued relation.", conceptId: "functions", domain: "discrete", anchor: "section-definition-function" },
  { term: "Function", text: "A function $f$ from set $A$ to set $B$ is a rule that assigns to each element $a \\in A$ exactly one element $f(a) \\in B$, written $f: A \\to B$. $A$ is the domain, $B$ the codomain, and the range (image) is $\\{ f(a) : a \\in A \\} \\subseteq B$.", conceptId: "function-basics", domain: "discrete", anchor: "section-definition-function" },
  { term: "Injective", text: "$f: A \\to B$ is injective (one-to-one) if $f(a) = f(b) \\implies a = b$ for all $a, b \\in A$. Equivalently: no two distinct inputs share an output.", conceptId: "injective-functions", domain: "discrete", anchor: "section-definition-injective" },
  { term: "Surjective", text: "$f: A \\to B$ is surjective (onto) if for every $b \\in B$ there exists $a \\in A$ with $f(a) = b$. Range = codomain.", conceptId: "surjective-functions", domain: "discrete", anchor: "section-definition-surjective" },
  { term: "Bijective", text: "$f: A \\to B$ is bijective if it is both injective and surjective. Bijections are exactly the functions with inverses.", conceptId: "bijective-functions", domain: "discrete", anchor: "section-definition-bijective" },
  { term: "Composition", text: "For $f: A \\to B$ and $g: B \\to C$, the composition $g \\circ f : A \\to C$ is $(g \\circ f)(a) = g(f(a))$. Read right to left: f first, then g.", conceptId: "function-composition", domain: "discrete", anchor: "section-definition-composition" },
  { term: "Inverse function", text: "If $f: A \\to B$ is bijective, its inverse $f^{-1}: B \\to A$ is the unique function with $f^{-1}(f(a)) = a$ for all $a$ and $f(f^{-1}(b)) = b$ for all $b$.", conceptId: "inverse-functions", domain: "discrete", anchor: "section-definition-inverse-function" },
  { term: "Binary relation", text: "A relation $R$ from $A$ to $B$ is a subset of the Cartesian product, $R \\subseteq A \\times B$, and we write $a \\mathrel{R} b$ to mean $(a,b) \\in R$. A relation on a set $A$ is a subset of $A \\times A$. Nothing more is required — which is exactly why relations are so general, and why the classification below is the interesting part.", conceptId: "relations", domain: "discrete", anchor: "section-definition-binary-relation" },
  { term: "Binary relation", text: "A binary relation from $A$ to $B$ is a subset $R \\subseteq A \\times B$. We write $a \\mathrel{R} b$ for $(a,b) \\in R$. On a single set $A$, $R \\subseteq A \\times A$ is a relation on $A$. The **inverse** relation is $R^{-1} = \\{(b,a) : (a,b) \\in R\\} \\subseteq B \\times A$.", conceptId: "relation-basics", domain: "discrete", anchor: "section-definition-binary-relation" },
  { term: "The four properties (relation R on A)", text: "**Reflexive:** $\\forall a \\in A,\\ a \\mathrel{R} a$. **Symmetric:** $a \\mathrel{R} b \\Rightarrow b \\mathrel{R} a$. **Antisymmetric:** $a \\mathrel{R} b \\land b \\mathrel{R} a \\Rightarrow a = b$. **Transitive:** $a \\mathrel{R} b \\land b \\mathrel{R} c \\Rightarrow a \\mathrel{R} c$. Note what antisymmetry does not say: it does not demand that every pair be comparable. Incomparable pairs are allowed and are the whole reason partial orders are interesting.", conceptId: "relation-properties", domain: "discrete", anchor: "section-definition-the-four-properties-relation-r-on-a" },
  { term: "Equivalence relation", text: "A relation $R$ on $A$ is an equivalence relation if it is reflexive, symmetric, and transitive. Its equivalence classes are $[a] = \\{ x \\in A : x \\mathrel{R} a \\}$, and the quotient set $A/{\\sim}$ is the set of classes.", conceptId: "equivalence-relations", domain: "discrete", anchor: "section-definition-equivalence-relation" },
  { term: "Partial order", text: "A relation $\\preceq$ on $A$ is a partial order if it is reflexive ($a \\preceq a$), antisymmetric ($a \\preceq b$ and $b \\preceq a$ imply $a = b$), and transitive ($a \\preceq b$ and $b \\preceq c$ imply $a \\preceq c$). The pair $(A, \\preceq)$ is a **poset**. A **total** (linear) order is a partial order in which every two elements are comparable. A **strict** partial order is the irreflexive version, $a \\prec b$ meaning $a \\preceq b$ and $a \\ne b$.", conceptId: "partial-orders", domain: "discrete", anchor: "section-definition-partial-order" },
  { term: "Lattice", text: "A poset $(L, \\preceq)$ is a **lattice** if every pair $a, b \\in L$ has (i) a **least upper bound** $a \\vee b$ (the **join**) and (ii) a **greatest lower bound** $a \\wedge b$ (the **meet**). If every subset has both — equivalently, if $L$ has a bottom $\\bot$ and top $\\top$ and arbitrary joins — it is a **complete lattice**. Meets and joins are commutative, associative, idempotent, and tied by the absorption laws: $a \\vee (a \\wedge b) = a$ and $a \\wedge (a \\vee b) = a$.", conceptId: "lattice-logic", domain: "discrete", anchor: "section-definition-lattice" },
  { term: "Recursive definition", text: "An object is defined recursively by **base cases** (objects given outright, with no reference to the definition) and **recursive rules** (each builds a new object from one or more already-defined, strictly smaller objects). Both halves are load-bearing: with no base case nothing is ever defined, and with no size restriction the definition can chase its own tail. The recursive rule may call the definition once (linear recursion), several times (tree recursion), or mutually.", conceptId: "recursion", domain: "discrete", anchor: "section-definition-recursive-definition" },
  { term: "Recursive definition", text: "A sequence $a_0, a_1, \\ldots$ is recursively defined by base values (for example $a_0$, or $a_0$ and $a_1$) and a rule expressing $a_n$ in terms of earlier terms. A set or structure is defined by base elements and constructors that build larger elements from smaller ones, plus the closure clause “nothing else is in the set”. That last clause is what makes the definition exact: it licenses induction on the construction.", conceptId: "recursive-definitions", domain: "discrete", anchor: "section-definition-recursive-definition" },
  { term: "Recurrence relation", text: "A recurrence for a sequence $T(n)$ expresses $T(n)$ in terms of $T$ at smaller arguments, together with base values. It is **linear** if $T$ appears only to the first power and no product $T(i)T(j)$ appears; **homogeneous** if every term contains $T$; of **order** $k$ if it refers back $k$ steps; and of **divide-and-conquer form** if it is $T(n) = a\\,T(n/b) + f(n)$ with $a \\ge 1$, $b > 1$.", conceptId: "recurrence-relations", domain: "discrete", anchor: "section-definition-recurrence-relation" },
  { term: "Dynamic programming", text: "A method for solving problems defined by a recurrence over a finite set of subproblems, evaluating each subproblem exactly once in an order where its dependencies are already solved. A DP solution is specified by four things: the **state** (what a subproblem is), the **transition** (the recurrence between states), the **order** (a topological order of the dependency graph: usually increasing size), and the **base cases**.", conceptId: "dynamic-programming", domain: "discrete", anchor: "section-definition-dynamic-programming" },
  { term: "Asymptotic analysis", text: "Choose a model of cost — typically the number of elementary operations, counted under a unit-cost RAM model where each arithmetic operation, comparison and memory access costs 1 — and express it as a function $T(n)$ of the **input size** $n$ (elements to sort, bits in the number, vertices plus edges in the graph). Asymptotic analysis then keeps the leading term of $T(n)$ and drops its constant factor. The result is a statement about a **family** of inputs of growing size, not about any single run.", conceptId: "asymptotics", domain: "discrete", anchor: "section-definition-asymptotic-analysis" },
  { term: "Formal definitions", text: "For positive functions $f, g$:\n\n$f \\in O(g)$ if $\\exists c > 0, n_0 : \\forall n \\ge n_0,\\; 0 \\le f(n) \\le c\\, g(n)$.\n\n$f \\in \\Omega(g)$ if $\\exists c > 0, n_0 : \\forall n \\ge n_0,\\; 0 \\le c\\, g(n) \\le f(n)$.\n\n$f \\in \\Theta(g)$ if $f \\in O(g)$ and $f \\in \\Omega(g)$.", conceptId: "asymptotic-notation", domain: "discrete", anchor: "section-definition-formal-definitions" },
  { term: "The arithmetic, stated precisely", text: "The shorthand $O(f) + O(g) = O(\\max(f, g))$ and $O(f) \\cdot O(g) = O(fg)$ are statements about sets of functions: the sum of any $f_1 \\in O(f)$ and $g_1 \\in O(g)$ lies in $O(\\max(f,g))$, and the product lies in $O(fg)$. Both follow from the definitions with explicit constants, and both are what let you read a program top to bottom instead of analysing it as a whole.", conceptId: "asymptotic-properties", domain: "discrete", anchor: "section-definition-the-arithmetic-stated-precisely" },
  { term: "The invariant", text: "Maintain a closed interval [lo, hi] known to contain the answer. Compare the midpoint mid = lo + ⌊(hi − lo)/2⌋ against the predicate; discard the half that cannot contain the answer. When lo = hi, the answer is lo. The algorithm is correct because the invariant is restored at every step and the interval length strictly decreases — no cleverness, just bookkeeping.", conceptId: "binary-search", domain: "discrete", anchor: "section-definition-the-invariant" },
  { term: "Boolean algebra (postulates)", text: "A Boolean algebra is a set $B$ with two binary operations $\\cdot$ and $+$, a unary operation $\\prime$, and elements $0, 1 \\in B$, satisfying: **commutativity** ($a+b = b+a$, $a\\cdot b = b\\cdot a$); **associativity**; **distributivity** ($a\\cdot(b+c) = a\\cdot b + a\\cdot c$ and, unusually, $a + b\\cdot c = (a+b)\\cdot(a+c)$, which is the rule ordinary arithmetic does not have); **identities** ($a + 0 = a$, $a \\cdot 1 = a$); and **complements** ($a + a^{\\prime} = 1$, $a \\cdot a^{\\prime} = 0$). Everything else — idempotence, absorption, De Morgan, consensus — is a derived law proved from these.", conceptId: "boolean-algebra", domain: "discrete", anchor: "section-definition-boolean-algebra-postulates" },
  { term: "Boolean expression", text: "Fix variables $x_1, \\ldots, x_n$. A **literal** is a variable or its complement ($x_i$ or $x_i^{\\prime}$). A Boolean expression is built from literals with $\\cdot$, $+$, and $\\prime$, and it defines a function $f: \\{0,1\\}^n \\to \\{0,1\\}$ by substituting bits and applying OR, AND, NOT. Two expressions are **equivalent** (written $\\equiv$) if they define the same function.", conceptId: "boolean-basics", domain: "discrete", anchor: "section-definition-boolean-expression" },
  { term: "Reading a definition", text: "A definition of the form “X is Y if and only if P” gives both directions: X ⇒ P and P ⇒ X. A definition of the form “let X be a Y such that P” gives the template: to use X, you know it is a Y satisfying P; to prove something is X, you must exhibit the Y and verify P.", conceptId: "definitions-terminology", domain: "proofs", anchor: "section-definition-reading-a-definition" },
  { term: "Structure of a direct proof of P ⇒ Q", text: "1. Assume P. 2. Derive intermediate facts, each justified. 3. Conclude Q. Written form: “Assume P. Then … [steps]. Therefore Q.”", conceptId: "direct-proof", domain: "proofs", anchor: "section-definition-structure-of-a-direct-proof-of-p-q" },
  { term: "Structure", text: "To prove P ⇒ Q: assume P and ¬Q. Derive a contradiction (R ∧ ¬R). Conclude Q. To prove ∃x P(x) by contradiction: assume ∀x ¬P(x) and derive R ∧ ¬R.", conceptId: "proof-by-contradiction", domain: "proofs", anchor: "section-definition-structure" },
  { term: "Structure", text: "To prove P ⇒ Q, prove ¬Q ⇒ ¬P by direct deduction. State the switch explicitly: “We prove the contrapositive: assume ¬Q…”", conceptId: "proof-by-contrapositive", domain: "proofs", anchor: "section-definition-structure" },
  { term: "Structure", text: "To prove ∀x P(x): partition the domain into C₁, …, Cₖ with C₁ ∪ … ∪ Cₖ = domain. Prove P(x) for x ∈ C₁, …, P(x) for x ∈ Cₖ. Conclude P(x) for all x.", conceptId: "proof-by-cases", domain: "proofs", anchor: "section-definition-structure" },
  { term: "Principle of (weak) induction", text: "To prove $P(n)$ for all $n \\ge n_0$: (1) **Base**: prove $P(n_0)$. (2) **Step**: prove $P(k) \\Rightarrow P(k+1)$ for an arbitrary $k \\ge n_0$. Then $P(n)$ holds for all $n \\ge n_0$.", conceptId: "mathematical-induction", domain: "proofs", anchor: "section-definition-principle-of-weak-induction" },
  { term: "Strong induction", text: "To prove $P(n)$ for all $n \\ge n_0$: (1) Base cases as needed. (2) **Strong step**: for an arbitrary $k$, assume $P(n)$ for all $n_0 \\le n < k$, and prove $P(k)$. Then $P(n)$ holds for all $n \\ge n_0$.", conceptId: "strong-induction", domain: "proofs", anchor: "section-definition-strong-induction" },
  { term: "Well-ordering principle", text: "Every nonempty subset of the positive integers has a least element.", conceptId: "well-ordering-principle", domain: "proofs", anchor: "section-definition-well-ordering-principle" },
  { term: "Constructive vs nonconstructive", text: "A **constructive** existence proof exhibits the object (or an algorithm to find it). A **nonconstructive** proof shows that the object must exist without producing it — typically by counting (pigeonhole) or contradiction.", conceptId: "existence-proof", domain: "proofs", anchor: "section-definition-constructive-vs-nonconstructive" },
  { term: "Standard structure", text: "To prove $\\exists! x, P(x)$: (1) **Existence**: show some $x$ with $P(x)$. (2) **Uniqueness**: if $P(a)$ and $P(b)$, then $a = b$.", conceptId: "uniqueness-proof", domain: "proofs", anchor: "section-definition-standard-structure" },
  { term: "Fundamental Counting Principle", text: "If a task can be broken into k sequential stages, and stage i has nᵢ possible choices regardless of earlier choices, then the total number of ways to complete the task is $\\prod_{i=1}^{k} n_i$. (This is exactly $|A_1 \\times \\cdots \\times A_k| = \\prod |A_i|$ for the Cartesian product.)", conceptId: "fundamental-counting", domain: "combinatorics", anchor: "section-definition-fundamental-counting-principle" },
  { term: "The rules", text: "**Addition rule**: if A and B are disjoint sets, |A ∪ B| = |A| + |B|. **Multiplication rule**: |A × B| = |A|·|B|.", conceptId: "addition-multiplication-rules", domain: "combinatorics", anchor: "section-definition-the-rules" },
  { term: "Permutations", text: "$P(n, k) = \\frac{n!}{(n-k)!}$ counts ordered selections of k distinct items from n. For k = n: $n!$ — the number of orderings of all n items.", conceptId: "permutations", domain: "combinatorics", anchor: "section-definition-permutations" },
  { term: "Combinations", text: "$\\binom{n}{k} = C(n,k) = \\frac{n!}{k!(n-k)!}$ counts the k-element subsets of an n-element set. Derivation: P(n,k) ordered selections, divided by k! (the orders per subset).", conceptId: "combinations", domain: "combinatorics", anchor: "section-definition-combinations" },
  { term: "Pigeonhole principle (PHP)", text: "If n + 1 (or more) objects are placed into n boxes, then some box contains at least two objects. General form: placing N objects into k boxes forces some box to hold at least ⌈N/k⌉.", conceptId: "pigeonhole-principle", domain: "combinatorics", anchor: "section-definition-pigeonhole-principle-php" },
  { term: "Inclusion–exclusion", text: "For sets $A_1, \\ldots, A_k$: $|A_1 \\cup \\cdots \\cup A_k| = \\sum_i |A_i| - \\sum_{i<j} |A_i \\cap A_j| + \\sum_{i<j<l} |A_i \\cap A_j \\cap A_l| - \\cdots + (-1)^{k+1} |A_1 \\cap \\cdots \\cap A_k|$. General principle: an element in exactly r of the sets is counted $\\sum_{j=1}^{r} (-1)^{j+1} \\binom{r}{j} = 1$ times.", conceptId: "inclusion-exclusion", domain: "combinatorics", anchor: "section-definition-inclusionexclusion" },
  { term: "Stars and bars", text: "The number of nonnegative integer solutions to $x_1 + x_2 + \\cdots + x_k = n$ is $\\binom{n + k - 1}{k - 1}$. (Positive solutions: $\\binom{n-1}{k-1}$.)", conceptId: "stars-and-bars", domain: "combinatorics", anchor: "section-definition-stars-and-bars" },
  { term: "Derangement", text: "A derangement of n elements is a permutation π with π(i) ≠ i for all i. Let D(n) be the count.", conceptId: "derangements", domain: "combinatorics", anchor: "section-definition-derangement" },
  { term: "Catalan numbers", text: "$C_n = \\frac{1}{n+1}\\binom{2n}{n}$: 1, 1, 2, 5, 14, 42, 132, 429, … with recurrence $C_n = \\sum_{i=0}^{n-1} C_i C_{n-1-i}$ and $C_{n+1} = \\frac{2(2n+1)}{n+2} C_n$.", conceptId: "catalan-numbers", domain: "combinatorics", anchor: "section-definition-catalan-numbers" },
  { term: "Graph", text: "A (simple undirected) graph is $G = (V, E)$ with a finite vertex set $V$ and an edge set $E \\subseteq \\{\\{u,v\\} : u, v \\in V,\\; u \\ne v\\}$. Write $uv \\in E$ or $u \\sim v$ when $u$ and $v$ are **adjacent** (neighbors); the neighbors of $u$ form $N(u)$.", conceptId: "graph-definition", domain: "graph-theory", anchor: "section-definition-graph" },
  { term: "Distance & diameter", text: "$d(u,v)$ = minimum length of a u–v path ($\\infty$ if none). The **diameter** of a connected graph is $\\max_{u,v} d(u,v)$; the **radius** is the minimum, over all vertices, of the vertex’s maximum distance (a center).", conceptId: "paths-walks-cycles", domain: "graph-theory", anchor: "section-definition-distance-diameter" },
  { term: "Definitions", text: "G is **connected** if every pair of vertices has a path between them. A **component** is a maximal connected subgraph; the component partition is computed by BFS/DFS. A **bridge** is an edge whose removal increases the number of components. An **articulation point** (cut vertex) is a vertex whose removal does the same.", conceptId: "connectivity", domain: "graph-theory", anchor: "section-definition-definitions" },
  { term: "MST", text: "For a connected weighted graph, a **minimum spanning tree** is a spanning tree of minimum total edge weight. An MST always exists; it is unique iff all edge weights are distinct.", conceptId: "minimum-spanning-trees", domain: "graph-theory", anchor: "section-definition-mst" },
  { term: "Hamiltonian", text: "A **Hamiltonian path** visits every vertex exactly once; a **Hamiltonian cycle** is a closed one. Deciding whether a graph has one is NP-complete (it generalizes 3-SAT via Karp’s reductions).", conceptId: "hamiltonian-paths", domain: "graph-theory", anchor: "section-definition-hamiltonian" },
  { term: "Graph coloring", text: "A **proper k-coloring** assigns one of k colors to each vertex so adjacent vertices differ. The **chromatic number** χ(G) is the smallest k. Two vertices may share a color iff they are non-adjacent — a coloring is a partition into independent sets.", conceptId: "graph-coloring", domain: "graph-theory", anchor: "section-definition-graph-coloring" },
  { term: "Topological order", text: "A **topological order** of a digraph G is a linear ordering of V such that for every edge u → v, u precedes v. Such an order exists iff G is a DAG.", conceptId: "topological-sorting", domain: "graph-theory", anchor: "section-definition-topological-order" },
  { term: "BFS", text: "From a source s: visit s; then all its unvisited neighbors; then their unvisited neighbors; … (a queue). BFS discovers every vertex at its true minimum distance from s in an unweighted graph — level by level.", conceptId: "bfs-dfs", domain: "graph-theory", anchor: "section-definition-bfs" },
  { term: "DFS", text: "From a source s: go as deep as possible along one branch before backtracking (a stack, or recursion). DFS produces a **DFS tree** plus cross/back/forward edges, and the finish-time ordering that powers topological sort, cycle detection, and strongly connected components.", conceptId: "bfs-dfs", domain: "graph-theory", anchor: "section-definition-dfs" },
  { term: "Dijkstra's algorithm", text: "Maintain tentative distances dist(·), initialized to 0 at s and ∞ elsewhere. Repeatedly pick the unsettled vertex u with smallest dist, settle it (final), and relax every outgoing edge u→v: if dist(u) + w(u,v) < dist(v), update dist(v) and parent(v). Stop when all are settled or the target is settled.", conceptId: "dijkstra", domain: "graph-theory", anchor: "section-definition-dijkstras-algorithm" },
  { term: "Bellman–Ford", text: "Initialize dist(s) = 0, others ∞. Repeat |V|−1 times: for every edge (u, v) with weight w, if dist(u) + w < dist(v), set dist(v) = dist(u) + w and parent(v) = u. One more pass: any further improvement means a negative cycle reachable from s.", conceptId: "bellman-ford", domain: "graph-theory", anchor: "section-definition-bellmanford" },
  { term: "Floyd–Warshall", text: "Let $d^{(k)}[i][j]$ be the shortest i→j distance using intermediate vertices from {1, …, k}. The recurrence: $d^{(k)}[i][j] = \\min\\big(d^{(k-1)}[i][j],\\; d^{(k-1)}[i][k] + d^{(k-1)}[k][j]\\big)$. Initialize $d^{(0)}[i][j] = w(i,j)$ (0 if i = j, ∞ if no edge). In-place over k gives O(V³) time, O(V²) space.", conceptId: "floyd-warshall", domain: "graph-theory", anchor: "section-definition-floydwarshall" },
  { term: "Flow network", text: "A digraph G = (V, E) with a source s, sink t, and capacities c(e) ≥ 0. A **flow** f assigns each edge a value 0 ≤ f(e) ≤ c(e) (capacity constraint) and conserves at every non-terminal vertex (inflow = outflow). Its **value** is the net outflow from s. A **max flow** maximizes the value; a **cut** (S, T) with s ∈ S, t ∈ T has capacity the sum of capacities of edges S→T.", conceptId: "network-flow", domain: "graph-theory", anchor: "section-definition-flow-network" },
  { term: "Kruskal’s algorithm", text: "Sort the edges by weight. Scan them in increasing order and add an edge iff its endpoints are in different components (test and merge with union–find). Stop after n − 1 edges. Correctness: at the moment an edge $e$ is accepted, $e$ is the lightest edge across the cut separating its two components, so the cut property forces it into every MST (of the contracted graph, hence of the original one). Complexity: $O(E \\log E)$ for the sort, plus near-constant union–find work — the sort dominates.", conceptId: "kruskal-prims", domain: "graph-theory", anchor: "section-definition-kruskals-algorithm" },
  { term: "Prim’s algorithm", text: "Start from any vertex; mark it visited. Repeatedly add the lightest edge from a visited vertex to an unvisited one, and mark the new vertex visited. Every added edge is lightest across the cut (visited, unvisited), so the cut property again certifies optimality. With a binary heap the running time is $O(E \\log V)$; with a Fibonacci heap, $O(E + V \\log V)$.", conceptId: "kruskal-prims", domain: "graph-theory", anchor: "section-definition-prims-algorithm" },
  { term: "The operations", text: "Each element has a pointer to its parent; a root points to itself and names the component. $\\texttt{find}(x)$ walks parent pointers to the root. $\\texttt{union}(x, y)$ calls find on both and points one root at the other. Everything hinges on keeping the trees shallow.", conceptId: "union-find", domain: "graph-theory", anchor: "section-definition-the-operations" },
  { term: "Residual graph and augmenting path", text: "Given a flow $f$ on a network with capacities $c$, the **residual capacity** of edge $(u,v)$ is $c_f(u,v) = c(u,v) - f(u,v)$ forward, plus $f(v,u)$ on the reverse edge (the amount of flow that can be cancelled). The **residual graph** contains every edge with positive residual capacity. An **augmenting path** is an s–t path in it; its **bottleneck** is the minimum residual capacity along the path. Pushing the bottleneck along the path keeps conservation and capacities valid and increases the flow value by exactly that bottleneck.", conceptId: "maximum-flow", domain: "graph-theory", anchor: "section-definition-residual-graph-and-augmenting-path" },
  { term: "Cut", text: "A **cut** $(S, T)$ of a flow network partitions the vertices with $s \\in S$ and $t \\in T$. Its **capacity** is the sum of the capacities of the edges from S to T: $c(S,T) = \\sum_{u \\in S, v \\in T} c(u,v)$. A **minimum cut** is one of least capacity. (Edges from T to S do not count — even though a real flow can push back along them, the net contribution is non-positive.)", conceptId: "max-flow-min-cut", domain: "graph-theory", anchor: "section-definition-cut" },
  { term: "Matching", text: "A **matching** M in a graph is a set of edges no two of which share a vertex. In a bipartite graph $G = (L \\cup R, E)$ a matching pairs each matched left vertex with a distinct right vertex. A **maximum matching** has the largest possible size; a **perfect matching** (on the left) matches every vertex of L. An **augmenting path** for M is a path that starts and ends at unmatched vertices and alternates unmatched/matched edges — flipping M along such a path increases the matching by one.", conceptId: "matching", domain: "graph-theory", anchor: "section-definition-matching" },
  { term: "Base-b representation", text: "Every positive integer n has a unique expansion $n = (d_k d_{k-1} \\ldots d_1 d_0)_b = \\sum_{i=0}^{k} d_i b^i$ with digits $0 \\le d_i < b$ and $d_k \\ne 0$. In base 10 we write the digits plainly; in base 2 we write, e.g., $(1011)_2 = 8 + 2 + 1 = 11$.", conceptId: "binary-arithmetic", domain: "number-theory", anchor: "section-definition-base-b-representation" },
  { term: "Even and odd", text: "An integer n is **even** if $n = 2k$ for some integer k; **odd** if $n = 2k + 1$. Equivalently: even iff $n \\bmod 2 = 0$. Every integer is exactly one of the two — the partition of ℤ into two residue classes mod 2.", conceptId: "parity", domain: "number-theory", anchor: "section-definition-even-and-odd" },
  { term: "Logarithm", text: "$\\log_b n = x$ means $b^x = n$. Common bases: $e$ (natural log, ln), 10 (log), 2 (log₂ — the default base in CS). Logarithms exist for n > 0.", conceptId: "logarithms", domain: "number-theory", anchor: "section-definition-logarithm" },
  { term: "Divisibility", text: "Integers a, b with a ≠ 0: we write $a \\mid b$ (“a divides b”) if there exists an integer k with $b = ak$. Then a is a **divisor** (factor) of b, and b is a **multiple** of a. In the division b ÷ a, a is the divisor, b the dividend, k = b/a the quotient.", conceptId: "divisibility-core", domain: "number-theory", anchor: "section-definition-divisibility" },
  { term: "Vocabulary", text: "**Factors** of n: positive divisors of n. **Factor pairs**: (d, n/d) for each divisor d. **Common factors** of a and b: factors shared by both; their largest is gcd(a, b). **Common multiples**: numbers divisible by both; their smallest positive one is lcm(a, b).", conceptId: "factors-and-multiples", domain: "number-theory", anchor: "section-definition-vocabulary" },
  { term: "Prime and composite", text: "An integer p > 1 is **prime** if its only positive divisors are 1 and p. An integer n > 1 that is not prime is **composite**. The number 1 is **neither** prime nor composite — excluding it is what makes the Fundamental Theorem of Arithmetic unique (otherwise 6 = 2·3 = 2·3·1 = … would have infinitely many “factorizations”).", conceptId: "primes", domain: "number-theory", anchor: "section-definition-prime-and-composite" },
  { term: "Miller–Rabin (one round)", text: "Write $n - 1 = 2^s d$ with d odd. Pick random base $2 \\le a \\le n-2$. Compute $x = a^d \\bmod n$. If $x \\in \\{1, n-1\\}$, n passes this round. Otherwise square: $x \\leftarrow x^2 \\bmod n$, up to s − 1 more times; if some $x = n-1$, pass; if no $n-1$ ever appears, n is **composite** (a is a witness).", conceptId: "primality-testing", domain: "number-theory", anchor: "section-definition-millerrabin-one-round" },
  { term: "GCD", text: "For integers a, b not both zero, $\\gcd(a, b)$ is the largest positive integer dividing both a and b. It is well-defined by the FTA: take the minimum exponent of each common prime.", conceptId: "gcd", domain: "number-theory", anchor: "section-definition-gcd" },
  { term: "LCM", text: "$\\mathrm{lcm}(a, b)$ is the smallest positive integer divisible by both a and b. From prime factorizations, take the **maximum** exponent of each prime (the gcd takes the minimum).", conceptId: "lcm", domain: "number-theory", anchor: "section-definition-lcm" },
  { term: "Congruence", text: "For n ≥ 1, integers a, b: $a \\equiv b \\pmod n$ reads “a is congruent to b modulo n” and means $n \\mid (a - b)$. Equivalently, a and b have the same remainder upon division by n.", conceptId: "congruence", domain: "number-theory", anchor: "section-definition-congruence" },
  { term: "Residue class", text: "$[a]_n = \\{ a + kn : k \\in \\mathbb{Z} \\}$ is the congruence class of a modulo n. There are exactly n classes: $[0], [1], \\ldots, [n-1]$, and every integer lies in exactly one (the division algorithm).", conceptId: "residue-classes", domain: "number-theory", anchor: "section-definition-residue-class" },
  { term: "Modular inverse", text: "$a^{-1} \\bmod n$ is the residue class $b$ with $ab \\equiv 1 \\pmod n$. It exists iff $\\gcd(a, n) = 1$, and is then unique modulo n.", conceptId: "modular-inverses", domain: "number-theory", anchor: "section-definition-modular-inverse" },
  { term: "Totient function", text: "$\\varphi(n)$ is the count of integers $1 \\le k \\le n$ with $\\gcd(k, n) = 1$ (equivalently, the number of units in $\\mathbb{Z}/n\\mathbb{Z}$).", conceptId: "euler-totient", domain: "number-theory", anchor: "section-definition-totient-function" },
  { term: "Kolmogorov axioms", text: "A probability space is $(\\Omega, \\mathcal{F}, P)$ where $\\Omega$ is the sample space, $\\mathcal{F}$ a σ-algebra of events, and $P: \\mathcal{F} \\to [0,1]$ satisfies: (1) $P(A) \\ge 0$ for all $A$, (2) $P(\\Omega)=1$, (3) If $A_1, A_2, \\dots$ are disjoint then $P(\\cup_i A_i)=\\sum_i P(A_i)$.", conceptId: "probability-axioms", domain: "probability", anchor: "section-definition-kolmogorov-axioms" },
  { term: "Sample space and event", text: "$\\Omega$ is the set of possible outcomes of an experiment. An event is a subset $A\\subseteq\\Omega$. The collection $\\mathcal{F}$ of events we can assign probability to must be closed under complement and countable union (a σ-algebra).", conceptId: "sample-spaces-events", domain: "probability", anchor: "section-definition-sample-space-and-event" },
  { term: "Equally likely", text: "If Ω is finite and each singleton has same probability $1/|Ω|$, then $P(A)=|A|/|Ω|$.", conceptId: "classical-probability", domain: "probability", anchor: "section-definition-equally-likely" },
  { term: "Conditional probability", text: "For $P(B)>0$, $P(A|B)=\\frac{P(A\\cap B)}{P(B)}$. Intuition: restrict sample space to $B$, renormalize.", conceptId: "conditional-probability", domain: "probability", anchor: "section-definition-conditional-probability" },
  { term: "Independence", text: "Events $A,B$ independent if $P(A\\cap B)=P(A)P(B)$. Random variables $X,Y$ independent if $P(X∈A, Y∈B)=P(X∈A)P(Y∈B)$ for all measurable $A,B$.", conceptId: "independence", domain: "probability", anchor: "section-definition-independence" },
  { term: "Random variable", text: "$X:Ω→ℝ$ measurable: {ω: X(ω)≤x}∈𝓕 for all x. CDF $F_X(x)=P(X≤x)$; for discrete, PMF $p_X(x)=P(X=x)$; for continuous with density $f$, $F_X(x)=∫_{-∞}^x f(t)dt$.", conceptId: "random-variables", domain: "probability", anchor: "section-definition-random-variable" },
  { term: "Expectation", text: "Discrete: $E[X]=\\sum_x x P(X=x)$. Continuous: $E[X]=\\int x f(x)dx$. For function $g$: $E[g(X)]=\\sum g(x)p(x)$ (law of the unconscious statistician).", conceptId: "expectation", domain: "probability", anchor: "section-definition-expectation" },
  { term: "Covariance", text: "$Cov(X,Y)=E[(X-E[X])(Y-E[Y])]=E[XY]-E[X]E[Y]$. $Var(X)=Cov(X,X)$. Correlation $ρ= Cov(X,Y)/(σ_X σ_Y) ∈ [-1,1]$.", conceptId: "variance-covariance", domain: "probability", anchor: "section-definition-covariance" },
  { term: "Binomial", text: "If $X=\\sum_{i=1}^n B_i$ with $B_i\\sim Bernoulli(p)$ i.i.d., then $P(X=k)=\\binom{n}{k}p^k(1-p)^{n-k}$, $E[X]=np$, $Var(X)=np(1-p)$.", conceptId: "bernoulli-binomial", domain: "probability", anchor: "section-definition-binomial" },
  { term: "Normal", text: "PDF $f(x)=\\frac{1}{\\sqrt{2πσ²}}e^{-(x-μ)²/2σ²}$, CDF $Φ$ no closed form, $E[X]=μ$, $Var=σ²$. Standard $Z=(X-μ)/σ∼N(0,1)$.", conceptId: "normal-distribution", domain: "probability", anchor: "section-definition-normal" },
  { term: "Markov chain", text: "State space S, transition matrix $P$ with $P_{ij}=P(X_{t+1}=j|X_t=i)$, $\\sum_j P_{ij}=1$. n-step $P^n$ gives n-step transition probabilities. Stationary $π$ satisfies $π=πP$, $\\sum π_i=1$.", conceptId: "markov-chains", domain: "probability", anchor: "section-definition-markov-chain" },
  { term: "M/M/1", text: "Poisson arrivals rate λ, exponential service rate μ, one server, infinite buffer, FIFO. Birth-death chain with birth λ, death μ. Stationary exists iff ρ=λ/μ<1. Then P(n in system)=(1-ρ)ρ^n, L=ρ/(1-ρ) average number, W=1/(μ-λ) average time in system (Little: L=λW).", conceptId: "queueing", domain: "probability", anchor: "section-definition-mm1" },
  { term: "Center", text: "Mean $\\bar x = \\frac1n\\sum x_i$ (sensitive to outliers, linear). Median = middle order statistic (robust, 50th percentile). Mode = most frequent (for categorical or multimodal).", conceptId: "measures-of-center", domain: "statistics", anchor: "section-definition-center" },
  { term: "Spread", text: "Range = max-min. IQR = Q3-Q1 (middle 50% width, robust). Variance $s²=\\frac1{n-1}\\sum (x_i-\\bar x)²$ (sample) or $σ²$ population; SD = √variance in same units.", conceptId: "measures-of-spread", domain: "statistics", anchor: "section-definition-spread" },
  { term: "Pearson correlation", text: "$r = \\frac{\\sum (x_i-\\bar x)(y_i-\\bar y)}{\\sqrt{\\sum (x_i-\\bar x)²\\sum (y_i-\\bar y)²}}$. r=1 perfect positive linear, -1 perfect negative, 0 no linear relation.", conceptId: "correlation", domain: "statistics", anchor: "section-definition-pearson-correlation" },
  { term: "Sampling distribution", text: "Fix population. Draw many samples size n, compute statistic T (e.g., mean). Distribution of T across samples is its sampling distribution. For mean: $E[\\bar X]=μ$, $Var(\\bar X)=σ²/n$, and by CLT $\\bar X≈N(μ,σ²/n)$ for large n.", conceptId: "sampling-distributions", domain: "statistics", anchor: "section-definition-sampling-distribution" },
  { term: "CI", text: "95% CI for mean (σ known): $\\bar x ± 1.96·σ/√n$. With σ unknown and large n, replace σ by s. Small n: use t-distribution.", conceptId: "confidence-intervals", domain: "statistics", anchor: "section-definition-ci" },
  { term: "Test", text: "Choose test statistic T. Compute p = P_{H0}(T ≥ observed). If p < α (e.g., 0.05), reject H0. Errors: Type I (false positive) = α, Type II (false negative) = β, power = 1-β.", conceptId: "hypothesis-testing", domain: "statistics", anchor: "section-definition-test" },
  { term: "Least squares", text: "Minimize $||y-Xβ||²$. Normal equations $X^TXβ=X^Ty$. For simple regression (one feature): slope $\\hat β1 = r·(s_y/s_x)$, intercept $\\hat β0=\\bar y-\\hat β1\\bar x$.", conceptId: "linear-regression", domain: "statistics", anchor: "section-definition-least-squares" },
  { term: "MLE", text: "$\\hat θ_{MLE}=argmax_θ L(θ)=argmax_θ \\sum_i log P(x_i|θ)$. Log turns product into sum, numerically stable.", conceptId: "maximum-likelihood", domain: "statistics", anchor: "section-definition-mle" },
  { term: "Bayes", text: "Posterior $∝$ Likelihood × Prior. MAP estimate = argmax posterior = argmax [log likelihood + log prior]. Prior acts as regularizer.", conceptId: "bayesian-statistics", domain: "statistics", anchor: "section-definition-bayes" },
  { term: "Vector", text: "A vector $v∈ℝ^n$ is an n-tuple $(v_1,...,v_n)$. Addition componentwise, scalar multiplication $c·v=(c v_1,...,c v_n)$. Geometrically: arrow from origin to point $v$.", conceptId: "vectors", domain: "linear-algebra", anchor: "section-definition-vector" },
  { term: "Operations", text: "Addition: $(u+v)_i=u_i+v_i$. Scaling: $(c u)_i=c u_i$. Linear combination: $∑ c_i v_i$.", conceptId: "vector-operations", domain: "linear-algebra", anchor: "section-definition-operations" },
  { term: "Dot product", text: "$u·v = \\sum_i u_i v_i$. Geometric: $u·v = ||u||·||v|| cosθ$, where θ is angle between them.", conceptId: "dot-product", domain: "linear-algebra", anchor: "section-definition-dot-product" },
  { term: "Cross product", text: "$a×b = (a_y b_z - a_z b_y, a_z b_x - a_x b_z, a_x b_y - a_y b_x)$. $|a×b|=|a||b|sinθ$. Direction via right-hand rule.", conceptId: "cross-product", domain: "linear-algebra", anchor: "section-definition-cross-product" },
  { term: "Matrix", text: "m×n matrix A has m rows, n columns. $A_{ij}$ row i col j. Transpose $A^T$ swaps rows/cols. Identity I has 1s on diagonal.", conceptId: "matrix-basics", domain: "linear-algebra", anchor: "section-definition-matrix" },
  { term: "Multiplication", text: "If A is m×n, B n×p, then AB is m×p with $(AB)_{ij}= row_i(A)·col_j(B) = \\sum_k A_{ik}B_{kj}$. Column view: columns of AB are linear combos of columns of A with coefficients from B.", conceptId: "matrix-multiplication", domain: "linear-algebra", anchor: "section-definition-multiplication" },
  { term: "Linear map", text: "$T$ linear iff $T(ax+by)=aT(x)+bT(y)$. Matrix representation: column j of A = T(e_j) where e_j basis vector. So $T(x)=Ax$.", conceptId: "linear-transformations", domain: "linear-algebra", anchor: "section-definition-linear-map" },
  { term: "Eigen", text: "Nonzero $v$ is eigenvector of A with eigenvalue λ if $Av=λv$. Characteristic polynomial det(A-λI)=0 gives eigenvalues.", conceptId: "eigenvalues-eigenvectors", domain: "linear-algebra", anchor: "section-definition-eigen" },
  { term: "Independence", text: "$v_1,...,v_k$ independent if $c_1v_1+...+c_kv_k=0$ ⇒ all $c_i=0$. Basis of V is independent set that spans V. Dimension = number of vectors in any basis.", conceptId: "linear-independence", domain: "linear-algebra", anchor: "section-definition-independence" },
  { term: "Least squares", text: "Overdetermined system $Ax=b$ (more equations than unknowns) generally has no solution. Least squares finds $x$ minimizing squared error $||Ax-b||²$. Solution via normal equations $A^TA x = A^T b$, or via QR or SVD for stability.", conceptId: "least-squares", domain: "linear-algebra", anchor: "section-definition-least-squares" },
  { term: "Projection", text: "$proj_v(u)=\\frac{u·v}{||v||²} v$. Orthogonal to $v$: $u-proj_v(u) ⊥ v$. Projection onto subspace $W$ with orthonormal basis $q_i$: $proj_W(u)=∑ (u·q_i) q_i$.", conceptId: "projections", domain: "linear-algebra", anchor: "section-definition-projection" },
  { term: "Determinant", text: "For 2×2 [[a,b],[c,d]]: det=ad-bc. For n×n: sum over permutations with sign, or via LU: product of U diagonal. det=0 ⇔ singular (collapses volume).", conceptId: "determinants", domain: "linear-algebra", anchor: "section-definition-determinant" },
  { term: "Inverse", text: "A^{-1} exists iff det(A)≠0. Then A^{-1}= (1/det) adj(A). 2×2: [[a,b],[c,d]]^{-1}=1/(ad-bc)[[d,-b],[-c,a]]. For larger, use Gaussian elimination on [A|I] → [I|A^{-1}].", conceptId: "identity-inverses", domain: "linear-algebra", anchor: "section-definition-inverse" },
  { term: "Elimination", text: "Transform augmented [A|b] via row ops: swap, scale, add multiple. Get upper triangular U, then back substitution. LU decomposition stores L (multipliers) and U: A=LU.", conceptId: "gaussian-elimination", domain: "linear-algebra", anchor: "section-definition-elimination" },
  { term: "Basis", text: "Basis of vector space V: set {v1,...,vn} independent and span(V)=V. Dimension dim(V)=n. Standard basis of ℝ^n: e1,...,en. Any vector has unique coordinates in a basis.", conceptId: "basis-dimension", domain: "linear-algebra", anchor: "section-definition-basis" },
  { term: "Diagonalizable", text: "A diagonalizable if ∃ invertible P with P^{-1}AP=D diagonal. Equivalent to having n linearly independent eigenvectors. Symmetric matrices always diagonalizable orthogonally: A=QΛQ^T.", conceptId: "diagonalization", domain: "linear-algebra", anchor: "section-definition-diagonalizable" },
  { term: "SVD", text: "A=UΣV^T: U m×m orthogonal (left singular vectors), Σ m×n diagonal σ_i≥0, V n×n orthogonal (right singular vectors). σ_i = sqrt(eig(A^T A)). Rank = number nonzero σ. Pseudoinverse A^+=V Σ^+ U^T.", conceptId: "svd", domain: "linear-algebra", anchor: "section-definition-svd" },
  { term: "PCA", text: "Center data X (n×d). Covariance C = X^T X/(n-1). Eigendecompose C=QΛQ^T. Columns of Q sorted by λ descending = principal components. Project X onto first k columns: k-dim representation preserving max variance.", conceptId: "pca-eigen-applications", domain: "linear-algebra", anchor: "section-definition-pca" },
  { term: "Cosine similarity", text: "For nonzero vectors u, v: $\\cos\\theta = \\dfrac{u \\cdot v}{\\lVert u \\rVert \\, \\lVert v \\rVert}$, where $\\theta$ is the angle between them. The value is 1 for same direction, 0 for orthogonal (unrelated), −1 for opposite. It equals the dot product of the two **unit** vectors — normalization is the whole definition.", conceptId: "cosine-similarity", domain: "linear-algebra", anchor: "section-definition-cosine-similarity" },
  { term: "Limit", text: "$\\lim_{x→a} f(x)=L$ if for every ε>0 there exists δ>0 such that $0<|x-a|<δ$ ⇒ $|f(x)-L|<ε$.", conceptId: "limits", domain: "calculus", anchor: "section-definition-limit" },
  { term: "Continuity", text: "f continuous at a if $\\lim_{x→a} f(x)=f(a)$ (limit exists, equals value). Continuous on interval if continuous at each point.", conceptId: "continuity", domain: "calculus", anchor: "section-definition-continuity" },
  { term: "Derivative", text: "$f'(a)=\\lim_{h→0} \\frac{f(a+h)-f(a)}{h}$ if limit exists. Geometrically slope of tangent line. $f$ differentiable at a ⇒ continuous at a.", conceptId: "derivative", domain: "calculus", anchor: "section-definition-derivative" },
  { term: "Critical point", text: "c critical if f'(c)=0 or f'(c) does not exist and c in domain. Local max/min must be critical or boundary.", conceptId: "derivative-applications", domain: "calculus", anchor: "section-definition-critical-point" },
  { term: "Antiderivative", text: "$F$ is an antiderivative of $f$ on an interval $I$ if $F'(x) = f(x)$ for every $x \\in I$. The indefinite integral $\\int f(x)\\,dx = F(x) + C$ denotes the set of all antiderivatives. Linearity: $\\int (af + bg) = a\\int f + b\\int g$.", conceptId: "antiderivatives", domain: "calculus", anchor: "section-definition-antiderivative" },
  { term: "Riemann integral", text: "Partition $[a,b]$ as $a = x_0 < x_1 < \\cdots < x_n = b$ with widths $\\Delta x_i = x_i - x_{i-1}$ and pick sample points $x_i^* \\in [x_{i-1}, x_i]$. The Riemann sum is $\\sum_{i=1}^n f(x_i^*)\\,\\Delta x_i$. If these sums approach a single number $I$ as $\\max \\Delta x_i \\to 0$, regardless of the sample points, then $f$ is integrable and $\\int_a^b f(x)\\,dx = I$.", conceptId: "definite-integral", domain: "calculus", anchor: "section-definition-riemann-integral" },
  { term: "Sequence", text: "Function from ℕ to ℝ. Converges to L if ∀ε>0 ∃N such that n≥N ⇒ |a_n-L|<ε.", conceptId: "sequences", domain: "calculus", anchor: "section-definition-sequence" },
  { term: "Series", text: "Partial sum $S_N=∑_{n=1}^N a_n$. Series converges if $S_N$ converges.", conceptId: "series", domain: "calculus", anchor: "section-definition-series" },
  { term: "Taylor", text: "If f infinitely differentiable at a, Taylor series $∑ f^{(n)}(a)/n! (x-a)^n$. Taylor polynomial degree k is truncation; remainder $R_k = f^{(k+1)}(c)/(k+1)! (x-a)^{k+1}$ for some c between a,x (Lagrange form).", conceptId: "taylor-series", domain: "calculus", anchor: "section-definition-taylor" },
  { term: "Partial", text: "$∂f/∂x = \\lim_{h→0} (f(x+h,y)-f(x,y))/h$. Similarly for y. Higher order: $f_{xy}=∂/∂y(∂f/∂x)$. Clairaut: if continuous, $f_{xy}=f_{yx}$.", conceptId: "partial-derivatives", domain: "calculus", anchor: "section-definition-partial" },
  { term: "Gradient", text: "$∇f(x) = (∂f/∂x_1, ..., ∂f/∂x_n)^T$. Directional derivative in direction unit u: $D_u f = ∇f·u = |∇f|cosθ$, max when u parallel ∇f.", conceptId: "gradient", domain: "calculus", anchor: "section-definition-gradient" },
  { term: "Function", text: "f: A→B assigns each a∈A exactly one b∈B. Domain A, codomain B, range {f(a)|a∈A}. Composition (f∘g)(x)=f(g(x)). Inverse f^{-1} exists iff f bijective.", conceptId: "function-review", domain: "calculus", anchor: "section-definition-function" },
  { term: "Implicit", text: "If F(x,y)=0 defines y(x), differentiate: ∂F/∂x + ∂F/∂y·y'=0 ⇒ y' = -F_x/F_y (if F_y≠0).", conceptId: "implicit-differentiation", domain: "calculus", anchor: "section-definition-implicit" },
  { term: "Second order test", text: "If ∇f(a)=0, Hessian H=∇²f(a). If H positive definite (all eigenvalues >0) ⇒ local min; negative definite ⇒ local max; indefinite ⇒ saddle.", conceptId: "multivariable-optimization", domain: "calculus", anchor: "section-definition-second-order-test" },
  { term: "Computation graph", text: "A directed acyclic graph whose nodes are elementary operations ($+$, $\\times$, $\\exp$, $\\sigma$, …) and whose edges carry intermediate values. For an output $L$ and a node value $v$, the adjoint is $\\bar v = \\partial L / \\partial v$. The chain rule for graphs: $\\bar v = \\sum_{c \\in \\text{children}(v)} \\bar c\\,\\frac{\\partial c}{\\partial v}$.", conceptId: "differentiation-rules-calc", domain: "calculus", anchor: "section-definition-computation-graph" },
  { term: "Optimization problem", text: "Minimize $f:ℝ^n→ℝ$ over feasible set $S⊆ℝ^n$: $\\min_{x∈S} f(x)$. $f$ objective, $S$ defined by constraints $g_i(x)≤0$, $h_j(x)=0$. Unconstrained: $S=ℝ^n$. Local min: $∃δ>0$ s.t. $f(x)≤f(y)$ for all $y$ with $||y-x||<δ$. Global min: $f(x)≤f(y)$ for all $y∈S$.", conceptId: "optimization-intro", domain: "optimization", anchor: "section-definition-optimization-problem" },
  { term: "Convex", text: "Set C convex if $∀x,y∈C, t∈[0,1]: tx+(1-t)y∈C$. Function f convex on convex domain if $f(tx+(1-t)y)≤t f(x)+(1-t)f(y)$. Strictly convex if < for x≠y, t∈(0,1). Concave = -convex.", conceptId: "convexity", domain: "optimization", anchor: "section-definition-convex" },
  { term: "GD", text: "Unconstrained min of differentiable f: iterate $x_{k+1}=x_k - η_k ∇f(x_k)$. η step size / learning rate. For convex f with L-Lipschitz gradient and η≤1/L, $f(x_k)-f* = O(1/k)$. With strong convexity, linear convergence $O((1-μ/L)^k)$.", conceptId: "gradient-descent", domain: "optimization", anchor: "section-definition-gd" },
  { term: "SGD", text: "Full gradient $∇f = \\frac1n\\sum_i ∇f_i$ expensive for large n. SGD samples mini-batch B: $g = \\frac1{|B|}\\sum_{i∈B} ∇f_i$, unbiased $E[g]=∇f$. Update $x←x-η g$. Variance reduced by larger batch or variance reduction (SVRG, SAGA).", conceptId: "stochastic-gradient-descent", domain: "optimization", anchor: "section-definition-sgd" },
  { term: "Newton", text: "Second-order approximation $f(x+δ)≈f(x)+∇f^T δ+½δ^T H δ$. Minimize quadratic: $H δ = -∇f$ ⇒ $δ = -H^{-1}∇f$. Update $x←x+δ$. For strongly convex with Lipschitz Hessian, locally quadratic convergence: error squares each step.", conceptId: "newtons-method", domain: "optimization", anchor: "section-definition-newton" },
  { term: "LP", text: "Standard form: min $c^Tx$ s.t. $Ax=b$, $x≥0$. Feasible set convex polyhedron. Fundamental theorem: if optimum exists, it occurs at extreme point (vertex).", conceptId: "linear-programming", domain: "optimization", anchor: "section-definition-lp" },
  { term: "Lagrange", text: "Min f(x) s.t. g(x)=0. Lagrangian $L(x,λ)=f(x)+λ g(x)$. Necessary condition at optimum (regular): $∇_x L=0$, $g=0$. Geometrically: level set of f tangent to constraint, gradients parallel.", conceptId: "lagrange-multipliers", domain: "optimization", anchor: "section-definition-lagrange" },
  { term: "Coordinates", text: "Point $P=(x,y)$ in plane, $P=(x,y,z)$ in space. Distance $d(P,Q)=\\sqrt{(x_1-x_2)^2+(y_1-y_2)^2}$. Midpoint $M=((x_1+x_2)/2,(y_1+y_2)/2)$. Slope $m=(y_2-y_1)/(x_2-x_1)$.", conceptId: "coordinate-geometry", domain: "geometry", anchor: "section-definition-coordinates" },
  { term: "Trig functions", text: "Unit circle: $cosθ = x$, $sinθ = y$. $tanθ = sinθ/cosθ$. $sec=1/cos$, $csc=1/sin$, $cot=cos/sin$. Period $2π$ for sin/cos, $π$ for tan. Pythagorean: $sin²θ+cos²θ=1$.", conceptId: "unit-circle-trig", domain: "geometry", anchor: "section-definition-trig-functions" },
  { term: "3D basics", text: "Plane: $ax+by+cz=d$, normal $n=(a,b,c)$. Line: $r(t)=p+tv$, $p$ point, $v$ direction. Two planes intersect in line (unless parallel). Line-plane intersection solves $a(p_x+t v_x)+...=d$ for t.", conceptId: "3d-geometry", domain: "geometry", anchor: "section-definition-3d-basics" },
  { term: "Conics", text: "Circle: $(x-h)²+(y-k)²=r²$. Ellipse: $(x-h)²/a²+(y-k)²/b²=1$. Parabola: $y=a(x-h)²+k$ (focus-directrix). Hyperbola: $(x-h)²/a²-(y-k)²/b²=1$. Discriminant $B²-4AC$: <0 ellipse (circle if A=C), =0 parabola, >0 hyperbola.", conceptId: "conic-sections", domain: "geometry", anchor: "section-definition-conics" },
  { term: "Isometry", text: "Preserves distances: translation, rotation, reflection (and composition). Similarity preserves angles (adds uniform scaling). Affine preserves parallelism (adds shear, non-uniform scaling). Projective preserves lines.", conceptId: "transformations-geometry", domain: "geometry", anchor: "section-definition-isometry" },
  { term: "Great circle", text: "Intersection of sphere with plane through center: shortest path (geodesic) on sphere. Any two non-antipodal points define unique great circle.", conceptId: "spherical-geometry", domain: "geometry", anchor: "section-definition-great-circle" },
  { term: "Group", text: "(G,*) is group if: (1) closure: a*b∈G, (2) associativity: (a*b)*c=a*(b*c), (3) identity e: e*a=a*e=a, (4) inverse: ∀a ∃a^{-1}: a*a^{-1}=e. Abelian if a*b=b*a.", conceptId: "groups", domain: "abstract-algebra", anchor: "section-definition-group" },
  { term: "Subgroup", text: "H≤G if closed under operation and inverses. Coset aH = {a*h | h∈H}. Left cosets partition G, all same size |H|.", conceptId: "subgroups", domain: "abstract-algebra", anchor: "section-definition-subgroup" },
  { term: "Ring", text: "(R,+,×): (R,+) abelian group, (R,×) associative, distributive: a(b+c)=ab+ac, (a+b)c=ac+bc. Commutative ring if × commutative. Ring with 1 if ∃1 with 1·a=a·1=a. Zero divisor: a≠0,b≠0 but ab=0.", conceptId: "rings", domain: "abstract-algebra", anchor: "section-definition-ring" },
  { term: "Field", text: "Field F: (F,+) abelian group, (F\\{0},×) abelian group, distributive. Finite field with q=p^k elements exists for prime p, k≥1, unique up to isomorphism: GF(q). GF(p)=ℤ_p with mod p arithmetic.", conceptId: "finite-fields", domain: "abstract-algebra", anchor: "section-definition-field" },
  { term: "Elliptic curve", text: "Over field F (char ≠2,3): $y² = x³ + ax + b$ with discriminant $4a³+27b²≠0$ (no cusp). Points (x,y) satisfying plus point at infinity O. Group law: O identity, inverse of (x,y) is (x,-y), addition via chord: line through P,Q meets curve at third point R, reflect to get P+Q.", conceptId: "elliptic-curves", domain: "abstract-algebra", anchor: "section-definition-elliptic-curve" },
  { term: "Polynomial ring", text: "R[x] = {a0+a1x+...+anx^n | ai∈R}. Degree, leading coeff. Over field, division algorithm: for f,g≠0, ∃q,r with f=qg+r, deg r < deg g.", conceptId: "polynomial-rings", domain: "abstract-algebra", anchor: "section-definition-polynomial-ring" },
  { term: "Entropy", text: "For discrete X with PMF p(x): $H(X)= -\\sum_x p(x)\\log_2 p(x)$ (bits). Convention $0\\log0=0$. Measures uncertainty / expected information content. $H(X)=E[-\\log p(X)]$.", conceptId: "entropy", domain: "information-theory", anchor: "section-definition-entropy" },
  { term: "Cross-entropy & KL", text: "Cross-entropy $H(p,q)=-\\sum p(x)\\log q(x)$. KL divergence $D_{KL}(p||q)=\\sum p(x)\\log\\frac{p(x)}{q(x)} = H(p,q)-H(p)$. $D_{KL}≥0$ with equality iff p=q (Gibbs inequality).", conceptId: "cross-entropy", domain: "information-theory", anchor: "section-definition-cross-entropy-kl" },
  { term: "MI", text: "$I(X;Y)=\\sum_{x,y} p(x,y)\\log\\frac{p(x,y)}{p(x)p(y)} = D_{KL}(p(x,y)||p(x)p(y))$. $I≥0$, 0 iff independent. Symmetric: I(X;Y)=I(Y;X). $I(X;Y)≤\\min(H(X),H(Y))$.", conceptId: "mutual-information", domain: "information-theory", anchor: "section-definition-mi" },
  { term: "Capacity", text: "Channel defined by $p(y|x)$. For input distribution $p(x)$, $I(X;Y)$ is mutual info. Capacity $C=\\max_{p(x)} I(X;Y)$: supremum of achievable reliable communication rates.", conceptId: "channel-capacity", domain: "information-theory", anchor: "section-definition-capacity" },
  { term: "Code", text: "Code C⊆Σ^n: set of codewords length n. Hamming distance d(x,y)=#positions differing. Minimum distance d_min = min_{x≠y∈C} d(x,y). Can detect up to d_min-1 errors, correct up to ⌊(d_min-1)/2⌋.", conceptId: "error-correction-codes", domain: "information-theory", anchor: "section-definition-code" },
  { term: "IEEE 754 double", text: "64 bits: 1 sign, 11 exponent (bias 1023), 52 mantissa (plus implicit leading 1). Value = (-1)^sign × 1.mantissa × 2^{exponent-bias}. Special: 0, ∞, NaN.", conceptId: "floating-point", domain: "numerical", anchor: "section-definition-ieee-754-double" },
  { term: "Conditioning", text: "Problem with input x, output f(x). Relative condition number κ = |x f'(x)/f(x)| (for scalar). If κ large, small input change → large output change: ill-conditioned, any algorithm will have large error. Stable algorithm: forward error ≤ C·κ·ε_mach.", conceptId: "numerical-stability", domain: "numerical", anchor: "section-definition-conditioning" },
  { term: "Methods", text: "Bisection: if f(a)f(b)<0 and continuous, root in [a,b]; halve interval each step, error halves (linear). Newton: x_{k+1}=x_k - f(x_k)/f'(x_k), quadratic convergence near simple root if f'≠0. Secant: approximates f' by finite difference, superlinear order ≈1.618.", conceptId: "root-finding", domain: "numerical", anchor: "section-definition-methods" },
  { term: "Quadrature", text: "Approximate integral by weighted sum ∑ w_i f(x_i). Trapezoid: (b-a)(f(a)+f(b))/2, error O((b-a)³f\"/12). Simpson: (b-a)/6·(f(a)+4f((a+b)/2)+f(b)), error O((b-a)^5 f^{(4)}/2880), exact for cubics. Composite: split into n subintervals, sum.", conceptId: "numerical-integration", domain: "numerical", anchor: "section-definition-quadrature" },
  { term: "Monte Carlo", text: "Want $I=E_p[f(X)]$. Sample $X_1,...,X_n∼p$ i.i.d., estimate $\\hat I_n = (1/n)∑ f(X_i)$. By LLN, $\\hat I_n→I$; by CLT, error ≈ σ/√n where σ²=Var(f(X)). Dimension independent — beats grid in high D.", conceptId: "monte-carlo", domain: "numerical", anchor: "section-definition-monte-carlo" },
  { term: "Gaussian elimination", text: "Transform [A|b] to upper triangular via row operations: swap rows (pivoting), add multiple of row to another. Then back substitution solves. LU: A=LU with L lower unit, U upper; solve Ly=b then Ux=y. Cost O(n³) flops.", conceptId: "systems-of-equations", domain: "numerical", anchor: "section-definition-gaussian-elimination" },
  { term: "Polynomial interpolation", text: "n+1 points with distinct x_i determine unique degree ≤n polynomial. Lagrange: $p(x)=∑ y_i ℓ_i(x)$ where $ℓ_i(x)=∏_{j≠i}(x-x_j)/(x_i-x_j)$. Newton: incremental with divided differences.", conceptId: "interpolation", domain: "numerical", anchor: "section-definition-polynomial-interpolation" },
  { term: "Language", text: "Alphabet Σ finite set of symbols. Σ* = all finite strings over Σ including ε (empty string, length 0). Language L is subset of Σ*. Operations: L1∪L2, L1L2={xy|x∈L1,y∈L2}, L*={ε}∪L∪LL∪... (zero or more concatenations), L+ = LL* (one or more).", conceptId: "formal-languages-basics", domain: "formal", anchor: "section-definition-language" },
  { term: "Regular", text: "Regular languages are smallest class containing ∅,{ε},{a} for each a∈Σ and closed under union, concatenation, star. Regex syntax: ∅, ε, a, R1|R2 (union), R1R2 (concat), R* (star), R+ = RR*, R? = ε|R. Precedence: * highest, then concat, then |.", conceptId: "regular-languages", domain: "formal", anchor: "section-definition-regular" },
  { term: "DFA", text: "DFA = (Q,Σ,δ:Q×Σ→Q, q0∈Q, F⊆Q). Extended δ̂(q,ε)=q, δ̂(q,wa)=δ(δ̂(q,w),a). Accepts w if δ̂(q0,w)∈F. NFA: δ:Q×(Σ∪{ε})→P(Q), accepts if some path from q0 to F spells w. NFA→DFA: subset construction: DFA states = subsets of NFA states, exponential blowup 2^n worst case.", conceptId: "finite-automata", domain: "formal", anchor: "section-definition-dfa" },
  { term: "CFG", text: "CFG G=(V,Σ,R,S) where V variables, Σ terminals disjoint, R productions A→α with A∈V, α∈(V∪Σ)*, S start. Derives via ⇒: replace variable by RHS. Language L(G)={w∈Σ* | S⇒*w}. Example S→aSb|ε generates {a^n b^n}.", conceptId: "context-free-languages", domain: "formal", anchor: "section-definition-cfg" },
  { term: "TM", text: "TM = (Q,Σ,Γ,δ,q0,q_accept,q_reject) where Γ⊇Σ tape alphabet with blank ⊔, δ:Q×Γ→Q×Γ×{L,R} transition. Configuration = tape contents + head pos + state. TM starts with input on tape, runs. Decides L if always halts and accepts iff w∈L. Recognizes L if accepts exactly w∈L (may loop otherwise). Church-Turing thesis: TM captures intuitive algorithm.", conceptId: "turing-machines", domain: "formal", anchor: "section-definition-tm" },
  { term: "P and NP", text: "P = ∪_k TIME(n^k): languages decidable in deterministic polynomial time. NP = ∪_k NTIME(n^k) = languages where membership has poly-size certificate verifiable in poly time: L∈NP iff ∃ poly-time verifier V with x∈L ⇔ ∃c, |c|=poly(|x|), V(x,c)=1.", conceptId: "complexity-classes", domain: "formal", anchor: "section-definition-p-and-np" },
  { term: "Classes", text: "Decidable (recursive): TM always halts, decides membership. Recognizable (r.e.): TM accepts if in language, may loop otherwise. Co-recognizable: complement recognizable. Theorem: L decidable iff L and complement both recognizable.", conceptId: "decidability", domain: "formal", anchor: "section-definition-classes" },
];
